import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';
import ProjectNavbar from '../../components/ProjectNavbar';
import '../../components/RealtimeWorkspace.css'; 

const InsuranceModule = () => {
  const context = useOutletContext();
  const resumeData = Array.isArray(context) ? context[0] : context?.resumeData;
  const setResumeData = Array.isArray(context) ? context[1] : context?.setResumeData;

  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState(null);
  const [loading, setLoading] = useState(false);

  // Sync state if it already exists globally
  useEffect(() => {
    if (resumeData && !Array.isArray(resumeData)) {
      setAnswer(resumeData);
    }
  }, [resumeData]);

  const handleQuery = async () => {
    setLoading(true);
    try {
      const response = await fetch('http://localhost:8000/api/insurance/query', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: question }),
      });
      const data = await response.json();
      
      // Update local view
      setAnswer(data);
      
      // CRITICAL HANDSHAKE: Store response globally for sub-pages (ins/p1, etc.)
      if (setResumeData) {
        setResumeData(data);
      }
    } catch (error) {
      console.error("Query failed:", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="workspace-container">
      <ProjectNavbar basePath="ins" links={["Claims", "Guardrails", "RAG", "Status"]} />
      
      <div className="metrics-grid">
        <div className="metric-card"><p>POLICY MATCH</p><h4>{answer ? `${answer.score || 94}%` : '94%'}</h4></div>
        <div className="metric-card"><p>LATENCY</p><h4>{answer ? `${answer.latency || 45}ms` : '45ms'}</h4></div>
        <div className="metric-card"><p>STATUS</p><h4 style={{color:'#22c55e'}}>● Secure</h4></div>
      </div>

      <header className="workspace-header">
        <h2 style={{ color: '#1e293b' }}>Insurance Claims Engine</h2>
      </header>

      <div className="input-section">
        <textarea 
          className="workspace-textarea"
          placeholder="Ask about policy coverage..."
          value={question}
          onChange={(e) => setQuestion(e.target.value)}
        />
        <button className="workspace-button" onClick={handleQuery} disabled={loading}>
          {loading ? 'Processing...' : 'Query AI Engine'}
        </button>
      </div>

      <div className="telemetry-log">
        <p>{'>'} Insurance Engine initialized...</p>
        {loading && <p>{'>'} Retrieving policy context...</p>}
      </div>

      {answer && (
        <div className="summary-box">
          <h3>AI Analysis Report</h3>
          <pre style={{ whiteSpace: 'pre-wrap', wordWrap: 'break-word' }}>
            {JSON.stringify(answer, null, 2)}
          </pre>
        </div>
      )}
    </div>
  );
};

export default InsuranceModule;
